@Composable fun FinalHub(context:Context){
 val p=remember{context.getSharedPreferences("narendar_final",Context.MODE_PRIVATE)}
 var grade by remember{mutableIntStateOf(p.getInt("grade",-1))};var screen by remember{mutableStateOf(if(grade<0)"pick" else "home")};var dark by remember{mutableStateOf(p.getBoolean("dark",false))};var xp by remember{mutableIntStateOf(p.getInt("xp",0))};var ok by remember{mutableIntStateOf(p.getInt("ok",0))};var tried by remember{mutableIntStateOf(p.getInt("tried",0))};var notes by remember{mutableStateOf(loadN(p))};var tasks by remember{mutableStateOf(loadT(p))};var toast by remember{mutableStateOf("")}
 fun choose(g:Int){grade=g;p.edit().putInt("grade",g).apply();screen="home"};fun saveN(v:List<N>){notes=v;p.edit().putString("notes",nJson(v)).apply()};fun saveT(v:List<T>){tasks=v;p.edit().putString("tasks",tJson(v)).apply()};fun answer(c:Boolean){tried++;if(c)ok++;xp+=if(c)20 else 5;p.edit().putInt("tried",tried).putInt("ok",ok).putInt("xp",xp).apply()}
 LaunchedEffect(toast){if(toast.isNotEmpty()){delay(1600);toast=""}}
 MaterialTheme(if(dark)darkColorScheme(primary=Color(0xFF9AB8FF),secondary=Color(0xFF70E0BE),tertiary=Color(0xFFD1A6FF))else lightColorScheme(primary=Color(0xFF315EFB),secondary=Color(0xFF00A884),tertiary=Color(0xFF7C4DFF))){
  if(screen=="pick"){Picker(grade,::choose);return@MaterialTheme}
  Scaffold(topBar={CenterAlignedTopAppBar(title={Text("Narendar Hub",fontWeight=FontWeight.Black)})},bottomBar={NavigationBar{listOf("home" to "⌂","learn" to "▣","quiz" to "✓","library" to "▤","profile" to "●").forEach{(s,i)->NavigationBarItem(screen==s,{screen=s},icon={Text(i)},label={Text(s.replaceFirstChar{it.uppercase()})})}}}){pad->Box(Modifier.fillMaxSize().padding(pad)){AnimatedContent(screen,transitionSpec={fadeIn(tween(220)) togetherWith fadeOut(tween(120))},label="screen"){s->when(s){"home"->Home(grade,xp,ok,tried,tasks.size,notes.size){screen=it};"learn"->Learn(grade){screen="quiz"};"quiz"->Quiz(grade,::answer){toast=it};"library"->Library(notes,tasks,::saveN,::saveT);"profile"->Profile(grade,xp,ok,tried,dark,{v->dark=v;p.edit().putBoolean("dark",v).apply()}){grade=-1;p.edit().putInt("grade",-1).apply();screen="pick"}}};AnimatedVisibility(toast.isNotEmpty(),enter=slideInVertically{it}+fadeIn(),exit=fadeOut(),modifier=Modifier.align(Alignment.BottomCenter).padding(8.dp)){Surface(shape=RoundedCornerShape(18.dp),tonalElevation=8.dp){Text(toast,Modifier.padding(15.dp),fontWeight=FontWeight.Bold)}}}}
 }
}

