eme.onSurfaceVariant);Spacer(Modifier.height(12.dp));Button(start,modifier=Modifier.fillMaxWidth()){Text("START TEST")}}}}}

@Composable private fun Quiz(g:Int,record:(Boolean)->Unit,toast:(String)->Unit){var subject by remember{mutableStateOf("Mathematics")};var diff by remember{mutableStateOf("Mixed")};var started by remember{mutableStateOf(false)};var count by remember{mutableIntStateOf(10)};var at by remember{mutableIntStateOf(0)};var score by remember{mutableIntStateOf(0)};var pick by remember{mutableIntStateOf(-1)};var done by remember{mutableStateOf(false)};val maxG=if(g<0)9 else g;val bank=remember(subject,diff,g){bank(maxG,subject,diff,2500)};val qs=remember(subject,diff,count,g){bank.shuffled().take(count)}
 if(!started){Column(Modifier.fillMaxSize().verticalScroll(rememberScrollState()).padding(16.dp)){Text("Quiz Arena",style=MaterialTheme.typography.headlineSmall,fontWeight=FontWeight.Black);Text("Game-like tests with class × subject × difficulty banks.",color=MaterialTheme.colorScheme.onSurfaceVariant);Spacer(Modifier.height(15.dp));Text("Subject",fontWeight=FontWeight.Black);Row(Modifier.horizontalScroll(rememberScrollState()),horizontalArrangement=Arrangement.spacedBy(6.dp)){(if(g>=9||g<0)subjects else subjects.take(6)).forEach{s->FilterChip(subject==s.name,{subject=s.name},label={Text(s.name)})}};Spacer(Modifier.height(10.dp));Text("Difficulty",fontWeight=FontWeight.Black);Row{listOf("Mixed","Easy","Medium","Hard").forEach{FilterChip(diff==it,{diff=it},label={Text(it)},modifier=Modifier.padding(end=4.dp))}};Spacer(Modifier.height(10.dp));Text("Test size",fontWeight=FontWeight.Black);Row{listOf(10,20,50,100).forEach{FilterChip(count==it,{count=it},label={Text("$it")},modifier=Modifier.padding(end=4.dp))}};Spacer(Modifier.height(18.dp));Card(Modifier.fillMaxWidth(),shape=RoundedCornerShape(24.dp)){Column(Modifier.padding(20.dp)){Text("🎮 Ready",fontSize=25.sp,fontWeight=FontWeight.Black);Text("Scope: ${if(g<0)"All classes" else "Class 1–$g"}\nSelected: $subject • $diff",color=MaterialTheme.colorScheme.onSurfaceVariant);Spacer(Modifier.height(12.dp));Button({started=true},modifier=Modifier.fillMaxWidth()){Text("ENTER ARENA")}}}};return}
 if(done){val a=score*100/count;Column(Modifier.fillMaxSize().padding(20.dp),horizontalAlignment=Alignment.CenterHorizontally){Spacer(Modifier.height(35.dp));Text("🏆",fontSize=64.sp);Text("Complete!",style=MaterialTheme.typography.headlineMedium,fontWeight=FontWeight.Black);Text("$score / $count",fontSize=32.sp,fontWeight=FontWeight.Black,color=MaterialTheme.colorScheme.primary);Text("Accuracy $a% • XP earned ${score*20}",color=MaterialTheme.colorScheme.onSurfaceVariant);Spacer(Modifier.height(20.dp));Button({started=false;done=false;at=0;score=0;pick=-1}){Text("PLAY AGAIN")}};return}
 val q=qs[at];Column(Modifier.fillMaxSize().verticalScroll(rememberScrollState()).padding(16.dp)){Row{Text("${at+1}/$count",fontWeight=FontWeight.Black);Spacer(Modifier.weight(1f));Text("+20 XP",color=MaterialTheme.colorScheme.primary,fontWeight=FontWeight.Bold)};Spacer(Modifier.height(7.dp));LinearProgressIndicator({(at.toFloat()+if(pick>=0)1 else 0)/count},Modifier.fillMaxWidth().height(8.dp));Spacer(Modifier.height(11.dp));Text("Class ${q.grade} • ${q.subject} • ${q.difficulty} • ${q.topic}",color=MaterialTheme.colorScheme.primary,fontSize=12.sp,fontWeight=FontWeight.Bold);Card(Modifier.fillMaxWidth().padding(vertical=10.dp),shape=RoundedCornerShape(24.dp)){Text(q.text,Modifier.padding(21.dp),fontSize=19.sp,fontWeight=FontWeight.Black)};q.options.forEachIndexed{i,o->val right=pick>=0&&i==q.answer;val wrong=pick==i&&pick!=q.answer;Card(onClick={if(pick<0)pick=i},modifier=Modifier.fillMaxWidth().padding(vertical=4.dp),shape=RoundedCornerShape(18.dp),colors=CardDefaults.cardColors(containerColor=when{right->Color(0xFFB7F7D5);wrong->Color(0xFFFFD0D0);pick==i->MaterialTheme.colorScheme.primaryContainer;else->MaterialTheme.colorScheme.surfaceVariant})){Row(Modifier.padding(16.dp)){Text("${('A'.code+i).toChar()}",fontWeight=FontWeight.Black);Spacer(Modifier.width(12.dp));Text(o,Modifier.weight(1f),fontWeight=if(right||pick==i)FontWeight.Bold else FontWeight.Normal);if(right)Text("✓")}}};AnimatedVisibility(pick>=0,enter=fadeIn()+expandVertically()){Column{Card(Modifier.fillMaxWidth().padding(top=8.dp),shape=RoundedCornerShape(18.dp)){Column(Modifier.padding(15.dp)){Text(if(pick==q.answer)"✨ Correct" else "📖 Explanation",fontWeight=FontWeight.Black,color=MaterialTheme.colorScheme.primary);Text(q.explanation,fontSize=13.sp,color=MaterialTheme.colorScheme.onSurfaceVariant)}};Button({val c=pick==q.answer;if(c)score++;record(c);if(at+1==count){done=true;toast("Quiz saved • XP updated")}else{at++;pick=-1}},modifier=Modifier.fillMaxWidth().padding(top=8.dp)){Text(if(at+1==count)"FINISH" else "NEXT")}}}}
}

private fun bank(maxG:Int,s:String,d:String,size:Int):List<Q>{val out=ArrayList<Q>(size);val ds=if(d=="Mixed")diffs else listOf(d);for(i in 0 until size){val g=i%max(1,maxG)+1;out+=make(g,s,ds[i%ds.size],i)};return out}
private fun make(g:Int,s:String,d:String,i:Int):Q{val n=abs((i+1)*7919+g*97+s.hashCode())%900+10;val topic=listOf("Basics","Core Concepts","Practice","Revision","Challenge")[i%5];return when(s){"Mathematics"->{val a=n%90+5;val b=n%37+2;val ans=when(i%4){0->a+b;1->a*b;2->a-b;else->a*a};val text=when(i%4){0->"What is $a + $b?";1->"What is $a × $b?";2->"What is $a − $b?";else->"What is the square of $a?"};numQ(g,d,topic,i,text,ans)};"Science"->fixed(g,s,d,topic,i,listOf(Triple("Which process do green plants use to make food?",listOf("Photosynthesis","Digestion","Evaporation","Filtration"),0),Triple("Which force pulls objects toward Earth?",listOf("Friction","Gravity","Magnetism","Buoyancy"),1),Triple("Which organ pumps blood?",listOf("Lung","Brain","Heart","Kidney"),2),Triple("Water changes from liquid to gas by what?",listOf("Freezing","Condensation","Evaporation","Melting"),2))[i%4]);"Computer Science"->fixed(g,s,d,topic,i,listOf(Triple("What does CPU stand for?",listOf("Central Processing Unit","Computer Power Utility","Core Program User","Central Print Unit"),0),Triple("Which language structures a web page?",listOf("HTML","SQL","CSS","BIOS"),0),Triple("Which number system uses 0 and 1?",listOf("Decimal","Binary","Octal","Roman"),1),Triple("Which is an operating system?",listOf("Android","HTML","JPEG","USB"),0))[i%4]);"English"->fixed(g,s,d,topic,i,listOf(Triple("Choose the correct sentence.",listOf("She go home.","She goes home.","She going home.","She gone home."),1),Triple("Opposite of ancient?",listOf("Modern","Old","Historic","Past"),0),Triple("Which word is a noun?",listOf("Beautiful","Run","Teacher","Quickly"),2),Triple("Correct plural of child?",listOf("Childs","Children","Childes","Childrens"),1))[i%4]);"SST"->fixed(g,s,d,topic,i,listOf(Triple("Which is a branch of social studies?",listOf("Geography","Algebra","Chemistry","Geometry"),0),Triple("Which tool represents locations on Earth?",listOf("Map","Thermometer","Scale","Stopwatch"),0),Triple("What does a constitution generally describe?",listOf("Basic rules of government","Weather","Chemical formulae","Multiplication facts"),0),Triple("Why do societies create laws?",listOf("To organize behavior","To change gravity","To stop seasons","To create planets"),0))[i%4]);"Urdu"->fixed(g,s,d,topic,i,listOf(Triple("'کتاب' کس قسم کا لفظ ہے؟",listOf("اسم","فعل","حرف","صفت"),0),Triple("'خوش' کی ضد کیا ہے؟",listOf("غمگین","تیز","اونچا","روشن"),0),Triple("'دوڑنا' کس قسم کا لفظ ہے؟",listOf("اسم","فعل","حرف","صفت"),1),Triple("'باغ' کا تعلق کس چیز سے ہے؟",listOf("جگہ","آواز","عدد","رنگ"),0))[i%4]);"Physics"->fixed(g,s,d,topic,i,listOf(Triple("SI unit of force?",listOf("Joule","Newton","Watt","Pascal"),1),Triple("Speed is distance divided by?",listOf("Mass","Time","Force","Energy"),1),Triple("Energy of motion?",listOf("Kinetic","Chemical","Nuclear","Stored"),0),Triple("Device measuring current?",listOf("Ammeter","Barometer","Thermometer","Hygrometer"),0))[i%4]);"Chemistry"->fixed(g,s,d,topic,i,listOf(Triple("Smallest unit retaining an element's identity?",listOf("Atom","Cell","Planet","Tissue"),0),Triple("Which particle is negative?",listOf("Proton","Neutron","Electron","Nucleus"),2),Triple("pH below 7 is?",listOf("Acidic","Neutral","Basic","Metallic"),0),Triple("H2O is?",listOf("Oxygen","Water","Hydrogen","Salt"),1))[i%4]);else->fixed(g,s,d,topic,i,listOf(Triple("Basic unit of life?",listOf("Cell","Atom","Organ","Tissue"),0),Triple("Powerhouse of the cell?",listOf("Nucleus","Mitochondrion","Ribosome","Vacuole"),1),Triple("Process plants use to make food?",listOf("Photosynthesis","Digestion","Filtration","Respiration"),0),Triple("What carries oxygen in blood?",listOf("Red blood cells","Platelets","Neurons","Bone cells"),0))[i%4])}}
private fun fixed(g:Int,s:String,d:String,t:String,i:Int,x:Triple<String,List<String>,Int>):Q=Q(i,g,s,d,t,x.first,x.second,x.third,"Correct answer: ${x.second[x.third]}. Review this concept before retrying the question.")
private fun numQ(g:Int,d:String,t:String,i:Int,text:String,a:Int):Q{val o=listOf(a,a+5+i%3,max(0,a-7),a+12).distinct().take(4).shuffled();return Q(i,g,"Mathematics",d,t,text,o.map{it.toString()},o.indexOf(a),"Work through the operation step by step. The correct result is $a.")}

@OptIn(ExperimentalMaterial3Api::class)
@Composable private fun Library(notes:List<N>,tasks:List<T>,saveN:(List<N>)->Unit,saveT:(List<T>)->Unit){var tab by remember{mutableStateOf("Notes")};var title by remember{mutableStateOf("")};var body by remember{mutableStateOf("")};var task by remember{mutableStateOf("")};var sec by remember{mutableIntStateOf(1500)};var run by remember{mutableStateOf(false)};var fi by remember{mutableIntStateOf(0)};LaunchedEffect(run){while(run&&sec>0){delay(1000);sec--};if(sec==0)run=false};Column(Modifier.fillMaxSize().padding(16.dp)){Text("Library & Tools",style=MaterialTheme.typography.headlineSmall,fontWeight=FontWeight.Black);Row(Modifier.horizontalScroll(rememberScrollState()),horizontalArrangement=Arrangement.spacedBy(6.dp)){listOf("Notes","Flashcards","Planner","Focus","Tools").forEach{FilterChip(tab==it,{tab=it},label={Text(it)})}};Spacer(Modifier.height(12.dp));when(tab){"Notes"->{OutlinedTextField(title,{title=it},Modifier.fillMaxWidth(),label={Text("Title")});Spacer(Modifier.height(6.dp));OutlinedTextField(body,{body=it},Modifier.fillMaxWidth().height(110.dp),label={Text("Note")});Button({if(title.isNotBlank()||body.isNotBlank()){saveN(notes+N(System.currentTimeMillis(),title.ifBlank{"Untitled"},body,"General"));title="";body=""}},modifier=Modifier.fillMaxWidth().padding(top=6.dp)){Text("SAVE NOTE")};Spacer(Modifier.height(8.dp));LazyColumn{items(notes.reversed()){n->Card(Modifier.fillMaxWidth().padding(vertical=4.dp)){Column(Modifier.padding(12.dp)){Row{Text(n.title,Modifier.weight(1f),fontWeight=FontWeight.Black);Text("×",Modifier.clickable{saveN(notes.filter{it.id!=n.id})})};Text(n.body,fontSize=13.sp)}}}}};"Flashcards"->{val cards=listOf("CPU" to "Central Processing Unit","Photosynthesis" to "Plants make food using light","Binary" to "Base-2 system: 0 and 1","Force" to "A push or pull");val c=cards[fi%cards.size];var flip by remember(fi){mutableStateOf(false)};Column(horizontalAlignment=Alignment.CenterHorizontally){Card(onClick={flip=!flip},modifier=Modifier.fillMaxWidth().height(230.dp),shape=RoundedCornerShape(28.dp)){Box(Modifier.fillMaxSize(),contentAlignment=Alignment.Center){Text(if(flip)c.second else c.first,fontSize=if(flip)18.sp else 34.sp,fontWeight=FontWeight.Black,textAlign=TextAlign.Center)}};Row{OutlinedButton({fi++}){Text("REVISE")};Button({fi++}){Text("KNOWN")}}}};"Planner"->{OutlinedTextField(task,{task=it},Modifier.fillMaxWidth(),label={Text("Task")});Button({if(task.isNotBlank()){saveT(tasks+T(System.currentTimeMillis(),task,false));task=""}},modifier=Modifier.fillMaxWidth().padding(top=6.dp)){Text("ADD TASK")};LazyColumn{items(tasks){x->Row(Modifier.fillMaxWidth().padding(5.dp),verticalAlignment=Alignment.CenterVertically){Checkbox(x.done,{v->saveT(tasks.map{if(it.id==x.id)it.copy(done=v)else it})});Text(x.text,Modifier.weight(1f));Text("×",Modifier.clickable{saveT(tasks.filter{it.id!=x.id})})}}}};"Focus"->{Column(horizontalAlignment=Alignment.CenterHorizontally,modifier=Modifier.fillMaxWidth()){Text("FOCUS MODE",fontWeight=FontWeight.Black);Spacer(Modifier.height(20.dp));Text(String.format(Locale.US,"%02d:%02d",sec/60,sec%60),fontSize=48.sp,fontWeight=FontWeight.Black);Row{Button({run=!run}){Text(if(run)"PAUSE" else "START")};OutlinedButton({run=false;sec=1500}){Text("RESET")}};Text("25 minute study focus session",color=MaterialTheme.colorScheme.onSurfaceVariant)}};"Tools"->Tools()}}}
@Composable private fun Tools(){var a by remember{mutableStateOf("")};var b by remember{mutableStateOf("")};var r by remember{mutableStateOf("")};Column{Text("Study Toolbox",fontWeight=FontWeight.Black);Row{OutlinedTextField(a,{a=it},Modifier.weight(1f),label={Text("A")});OutlinedTextField(b,{b=it},Modifier.weight(1f),label={Text("B")})};Row{listOf("+","−","×","÷").forEach{o->Button({r=calculate(a,b,o)},Modifier.weight(1f)){Text(o)}}};Text(r.ifBlank{"Result"},fontSize=24.sp,fontWeight=FontWeight.Black,modifier=Modifier.padding(15.dp));Text("Formula Vault",fontWeight=FontWeight.Black);listOf("Speed = distance ÷ time","Percentage = part ÷ whole × 100","Area = length × width","Force = mass × acceleration","V = I × R").forEach{Text("• $it",Modifier.padding(4.dp))};Text("7 table: ${List(10){7*(it+1)}.joinToString(" • ")}",fontWeight=FontWeight.Bold)}}
private fun calculate(a:String,b:String,o:String):String{val x=a.toDoubleOrNull()?:return "Enter A";val y=b.toDoubleOrNull()?:return "Enter B";return when(o){"+"->"${x+y}";"−"->"${x-y}";"×"->"${x*y}";else->if(y==0.0)"Cannot divide by zero" else "${x/y}"}}

@Composable private fun Profile(g:Int,xp:Int,ok:Int,tried:Int,dark:Boolean,setDark:(Boolean)->Unit,change:()->Unit){val acc=if(tried==0)0 else ok*100/tried;Column(Modifier.fillMaxSize().verticalScroll(rememberScrollState()).padding(16.dp)){Text("Player Profile",style=MaterialTheme.typography.headlineSmall,fontWeight=FontWeight.Black);Card(Modifier.fillMaxWidth().padding(vertical=12.dp),shape=RoundedCornerShape(24.dp)){Column(Modifier.padding(20.dp)){Text("Narendar",fontSize=25.sp,fontWeight=FontWeight.Black);Text(if(g<0)"All Classes" else "Class $g",color=MaterialTheme.colorScheme.primary);Text("Level ${xp/500+1} • $xp XP",fontWeight=FontWeight.Bold);LinearProgressIndicator({(xp%500)/500f},Modifier.fillMaxWidth().padding(vertical=8.dp));Text("Accuracy $acc% • Correct $ok • Attempted $tried")}};Text("Achievements",fontWeight=FontWeight.Black);listOf("🌱 First Steps","🔥 Streak","🎯 Accuracy","🏆 Champion","📚 Study Builder","⚡ XP Collector").forEachIndexed{i,t->Card(Modifier.fillMaxWidth().padding(3.dp)){Row(Modifier.padding(12.dp)){Text(t);Spacer(Modifier.weight(1f));Text(if(xp>=(i+1)*100)"UNLOCKED" else "LOCKED",fontSize=10.sp)}}};Row(Modifier.fillMaxWidth(),verticalAlignment=Alignment.CenterVertically){Text("Dark theme",Modifier.weight(1f));Switch(dark,setDark)};Button(change,modifier=Modifier.fillMaxWidth()){Text("CHANGE CLASS")};Text("Final offline learning platform • 60+ feature foundation",fontSize=12.sp,color=MaterialTheme.colorScheme.onSurfaceVariant,modifier=Modifier.padding(top=12.dp))}}

private fun loadN(p:android.content.SharedPreferences): List<N> = runCatching{val a=JSONArray(p.getString("notes","[]"));List(a.length()){val o=a.getJSONObject(it);N(o.getLong("id"),o.getString("title"),o.getString("body"),o.optString("subject","General"))}}.getOrDefault(emptyList())
private fun loadT(p:android.content.SharedPreferences): List<T> = runCatching{val a=JSONArray(p.getString("tasks","[]"));List(a.length()){val o=a.getJSONObject(it);T(o.getLong("id"),o.getString("text"),o.optBoolean("done",false))}}.getOrDefault(emptyList())
private fun nJson(v:List<N>):String=JSONArray().apply{v.forEach{put(JSONObject().apply{put("id",it.id);put("title",it.title);put("body",it.body);put("subject",it.subject)})}}.toString()
private fun tJson(v:List<T>):String=JSONArray().apply{v.forEach{put(JSONObject().apply{put("id",it.id);put("text",it.text);put("done",it.done)})}}.toString()
